const formatAdDate=(value:string)=>{const date=new Date(value);if(Number.isNaN(date.getTime()))return {label:'Date unavailable',today:false};const time=date.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit',hour12:true}).toLowerCase();const now=new Date();const today=date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()&&date.getDate()===now.getDate();return {label:today?`Today ${time}`:`${date.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} ${time}`,today}};
const toQrItem=(record:QrRecord):QrItem=>({id:String(record.id),name:record.name?.trim()||`QR ${record.id}`,rate:String(record.percentage),imps:String(record.imps??'0'),msg:record.msg||'',image:record.source});
