 useEffect(()=>{if(!authToken)return;const initial=setTimeout(()=>void loadNotifications(),0);const timer=setInterval(()=>void loadNotifications(),8000);return()=>{clearTimeout(initial);clearInterval(timer)}},[authToken,loadNotifications]);
 const openNotifications=()=>{setArea('home');setPanel('notifications');if(authToken){void fetch(NOTIFICATIONS_API_URL,{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${authToken}`}}).then(response=>{if(response.ok)setUnreadNotificationCount(0)}).catch(()=>{})}};
