 useEffect(()=>{if(!authToken)return;const initial=setTimeout(()=>void loadChatConversations(),0);const timer=setInterval(()=>void loadChatConversations(),8000);return()=>{clearTimeout(initial);clearInterval(timer)}},[authToken,loadChatConversations]);
 const[newQrName,setNewQrName]=useState(''),[newQrRate,setNewQrRate]=useState('1.0'),[newQrImps,setNewQrImps]=useState('0'),[newQrMsg,setNewQrMsg]=useState(''),[qrMessageSaving,setQrMessageSaving]=useState<string|null>(null),[newQrImage,setNewQrImage]=useState<PickedQrImage|null>(null),[bankNameInput,setBankNameInput]=useState(''),[bankDirectory,setBankDirectory]=useState<string[]>([]),[banksLoading,setBanksLoading]=useState(false),[bankSaving,setBankSaving]=useState(false),[bankDeleting,setBankDeleting]=useState<string|null>(null),[banksError,setBanksError]=useState(''),[bankToDelete,setBankToDelete]=useState<string|null>(null);
 const[area,setArea]=useState<Area>('home'),[panel,setPanel]=useState<Panel>('notifications'),[viewQr,setViewQr]=useState<{name:string;image:string|null}|null>(null),[viewAd,setViewAd]=useState<AdminAd|null>(null),[adToDelete,setAdToDelete]=useState<AdminAd|null>(null),[title,setTitle]=useState(''),[body,setBody]=useState(''),[ads,setAds]=useState<AdminAd[]>([]),[adsLoading,setAdsLoading]=useState(false),[adsSaving,setAdsSaving]=useState(false),[adDeleting,setAdDeleting]=useState<string|null>(null),[adsError,setAdsError]=useState(''),[qrItems,setQrItems]=useState<QrItem[]>([]),[qrLoading,setQrLoading]=useState(false),[qrSaving,setQrSaving]=useState(false),[qrDeleting,setQrDeleting]=useState<string|null>(null),[qrError,setQrError]=useState(''),[bankGroups,setBankGroups]=useState<BankGroup[]>([]),[cardGroupsLoading,setCardGroupsLoading]=useState(false),[cardGroupsSaving,setCardGroupsSaving]=useState(false),[cardGroupsError,setCardGroupsError]=useState(''),[percentageToDelete,setPercentageToDelete]=useState<string|null>(null),[percentageDeleting,setPercentageDeleting]=useState<string|null>(null),[bankAssignmentBusy,setBankAssignmentBusy]=useState<string|null>(null),[openBankGroup,setOpenBankGroup]=useState<string|null>(null),[newPercentage,setNewPercentage]=useState(''),[newImps,setNewImps]=useState('0'),[addingPercentage,setAddingPercentage]=useState(false),[messageSaving,setMessageSaving]=useState<string|null>(null);
 const loadQrItems=useCallback(async()=>{setQrLoading(true);setQrError('');try{const response=await fetch(QR_PERCENTAGES_API_URL,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Server returned ${response.status}.`);const data:unknown=await response.json();if(!Array.isArray(data))throw new Error('The QR response was not a list.');setQrItems(data.map(row=>toQrItem(row as QrRecord)))}catch(error){setQrError(error instanceof Error?error.message:'Could not load QR records. Check the backend connection.')}finally{setQrLoading(false)}},[setQrItems]);
 const loadBankNames=useCallback(async()=>{setBanksLoading(true);setBanksError('');try{const response=await fetch(BANK_NAMES_API_URL,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Server returned ${response.status}.`);const data:unknown=await response.json();if(!Array.isArray(data))throw new Error('The bank names response was not a list.');const names=data.map(row=>row&&typeof row==='object'&&'name' in row?String(row.name).trim():'').filter(Boolean);setBankDirectory(names)}catch(error){setBanksError(error instanceof Error?error.message:'Could not load bank names. Check the backend connection.')}finally{setBanksLoading(false)}},[setBankDirectory]);
 const loadAds=useCallback(async()=>{setAdsLoading(true);setAdsError('');try{const response=await fetch(ADS_API_URL,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Server returned ${response.status}.`);const data:unknown=await response.json();if(!Array.isArray(data))throw new Error('The ads response was not a list.');setAds(data as AdminAd[])}catch(error){setAdsError(error instanceof Error?error.message:'Could not load ads. Check the backend connection.')}finally{setAdsLoading(false)}},[]);
 const loadCardGroups=useCallback(async()=>{setCardGroupsLoading(true);setCardGroupsError('');try{const response=await fetch(CARD_PERCENTAGES_API_URL,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Server returned ${response.status}.`);const data:unknown=await response.json();if(!Array.isArray(data))throw new Error('The bank percentage response was not a list.');setBankGroups((data as CardPercentageRecord[]).map(row=>({id:row.percentage,percentage:row.percentage,msg:row.msg||'',imps:String(row.imps??'0'),banks:row.banks.map(name=>({id:name,name}))})))}catch(error){setCardGroupsError(error instanceof Error?error.message:'Could not load bank percentages. Check the backend connection.')}finally{setCardGroupsLoading(false)}},[setBankGroups]);
 const openArea=(next:Area)=>{setArea(next);if(next==='qr')void loadQrItems();if(next==='banks')void loadBankNames();if(next==='ads')void loadAds();if(next==='card'){void loadCardGroups();void loadBankNames()}};
 const addBankName=async()=>{const name=bankNameInput.trim();if(!name)return Alert.alert('Enter a bank name','Type a bank name before adding it.');setBankSaving(true);setBanksError('');try{const response=await fetch(BANK_NAMES_API_URL,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({name})});if(!response.ok){const result=await response.json().catch(()=>null);const message=typeof result?.name?.[0]==='string'?result.name[0]:`Server returned ${response.status}.`;throw new Error(message)}const created=await response.json() as {name:string};setBankDirectory(names=>[...names,created.name].sort((a,b)=>a.localeCompare(b)));setBankNameInput('')}catch(error){setBanksError(error instanceof Error?error.message:'Could not save the bank name. Check the backend connection.')}finally{setBankSaving(false)}};
 const deleteBankName=async(name:string)=>{setBankDeleting(name);setBanksError('');try{const response=await fetch(`${BANK_NAMES_API_URL}${encodeURIComponent(name)}/`,{method:'DELETE'});if(!response.ok)throw new Error(`Server returned ${response.status}.`);setBankDirectory(names=>names.filter(bank=>bank!==name));setBankGroups(groups=>groups.map(group=>({...group,banks:group.banks.filter(bank=>bank.name!==name)})));setBankToDelete(null)}catch(error){setBanksError(error instanceof Error?error.message:'Could not delete the bank name. Check the backend connection.');setBankToDelete(null)}finally{setBankDeleting(null)}};
 const addCardPercentage=async()=>{const value=newPercentage.trim(),impsValue=newImps.trim()||'0';if(!value||!Number.isFinite(Number(value))||Number(value)<0||Number(value)>100){setCardGroupsError('Enter a percentage between 0 and 100.');return}if(!Number.isFinite(Number(impsValue))||Number(impsValue)<0){setCardGroupsError('Enter a valid non-negative IMPS charge.');return}setCardGroupsSaving(true);setCardGroupsError('');try{const response=await fetch(CARD_PERCENTAGES_API_URL,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({percentage:value,imps:impsValue})});const result=await response.json().catch(()=>null);if(!response.ok){const message=typeof result?.percentage?.[0]==='string'?result.percentage[0]:typeof result?.imps?.[0]==='string'?result.imps[0]:`Server returned ${response.status}.`;throw new Error(message)}const created=result as {percentage:string;msg?:string;imps:string|number};const group={id:created.percentage,percentage:created.percentage,msg:created.msg||'',imps:String(created.imps??'0'),banks:[]};setBankGroups(groups=>[...groups,group]);setOpenBankGroup(created.percentage);setNewPercentage('');setNewImps('0');setAddingPercentage(false)}catch(error){setCardGroupsError(error instanceof Error?error.message:'Could not save the percentage. Check the backend connection.')}finally{setCardGroupsSaving(false)}};
 const updatePercentageMessage=async(group:BankGroup)=>{setMessageSaving(group.percentage);setCardGroupsError('');try{const response=await fetch(`${CARD_PERCENTAGES_API_URL}${encodeURIComponent(group.percentage)}/`,{method:'PATCH',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({msg:group.msg})});const result=await response.json().catch(()=>null);if(!response.ok){const message=typeof result?.msg?.[0]==='string'?result.msg[0]:`Server returned ${response.status}.`;throw new Error(message)}setBankGroups(groups=>groups.map(item=>item.percentage===group.percentage?{...item,msg:result.msg||''}:item))}catch(error){setCardGroupsError(error instanceof Error?error.message:'Could not save the availability message. Check the backend connection.')}finally{setMessageSaving(null)}};
 const deleteCardPercentage=async(percentage:string)=>{setPercentageDeleting(percentage);setCardGroupsError('');try{const response=await fetch(`${CARD_PERCENTAGES_API_URL}${encodeURIComponent(percentage)}/`,{method:'DELETE'});if(!response.ok)throw new Error(`Server returned ${response.status}.`);setBankGroups(groups=>groups.filter(group=>group.percentage!==percentage));setPercentageToDelete(null);if(openBankGroup===percentage)setOpenBankGroup(null)}catch(error){setCardGroupsError(error instanceof Error?error.message:'Could not delete the percentage. Check the backend connection.')}finally{setPercentageDeleting(null)}};
