 const chooseQrImage=async()=>{const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:true,quality:.9});if(!result.canceled){const asset=result.assets[0];setNewQrImage({uri:asset.uri,name:asset.fileName||`qr-${Date.now()}.jpg`,type:asset.mimeType||'image/jpeg'})}};
 const addQr=async()=>{const name=newQrName.trim();const percentage=Number(newQrRate),imps=Number(newQrImps||'0');if(!name||!newQrImage){setQrError('Enter a QR name and choose its image.');return}if(!Number.isFinite(percentage)||percentage<0||percentage>100){setQrError('Enter a percentage between 0 and 100.');return}if(!Number.isFinite(imps)||imps<0){setQrError('Enter a valid non-negative IMPS charge.');return}setQrSaving(true);setQrError('');try{const form=new FormData();form.append('name',name);form.append('percentage',String(percentage));form.append('imps',String(imps));form.append('msg',newQrMsg.trim());if(Platform.OS==='web'){const imageResponse=await fetch(newQrImage.uri);if(!imageResponse.ok)throw new Error('Could not read the selected QR image.');form.append('image',await imageResponse.blob(),newQrImage.name)}else{form.append('image',{uri:newQrImage.uri,name:newQrImage.name,type:newQrImage.type} as unknown as Blob)}const response=await fetch(QR_PERCENTAGES_API_URL,{method:'POST',headers:{Accept:'application/json'},body:form});if(!response.ok){const result=await response.json().catch(()=>null);const detail=result&&typeof result==='object'?Object.values(result as Record<string,unknown>).flatMap(value=>Array.isArray(value)?value:[]).find(value=>typeof value==='string'):null;throw new Error(typeof detail==='string'?detail:`Server returned ${response.status}.`)}const saved=await response.json() as QrRecord;setQrItems(items=>[toQrItem(saved),...items]);setNewQrName('');setNewQrRate('1.0');setNewQrImps('0');setNewQrMsg('');setNewQrImage(null)}catch(error){setQrError(error instanceof Error?error.message:'Could not save the QR. Check the backend connection.')}finally{setQrSaving(false)}};
