 const addAd=async()=>{const adTitle=title.trim(),description=body.trim();if(!adTitle||!description)return Alert.alert('Add ad details','Enter a title and message.');setAdsSaving(true);setAdsError('');try{const response=await fetch(ADS_API_URL,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json',Authorization:`Bearer ${authToken||''}`},body:JSON.stringify({title:adTitle,descript:description})});if(!response.ok){const result=await response.json().catch(()=>null);const message=Object.values((result||{}) as Record<string,unknown>).flatMap(value=>Array.isArray(value)?value:[]).find(value=>typeof value==='string');throw new Error(typeof message==='string'?message:`Server returned ${response.status}.`)}const created=await response.json() as AdminAd;setAds(items=>[created,...items]);setTitle('');setBody('')}catch(error){setAdsError(error instanceof Error?error.message:'Could not save the ad. Check the backend connection.')}finally{setAdsSaving(false)}};
